"""Temporal candidate policy with safety gating, target reacquisition, and
hysteretic motion selection to reduce needless instruction changes."""
# EVOLVE-BLOCK-START

MOTION_ACTIONS = ("FORWARD", "VEER_LEFT", "VEER_RIGHT")


def safety_contract(observation, memory):
    """Stop whenever confidence is low or collision risk exceeds the limit."""
    if (
        float(observation["safety_confidence"]) < 0.60
        or float(observation["closing_risk"]) >= 0.75
    ):
        memory["state"] = "STOPPED"
        memory["last_action"] = "STOP"
        memory["action_age"] = 0
        return "STOP", 0.99
    return None


def tracking_contract(observation, memory):
    """Verify a stable target and use bounded, non-advancing recovery when lost."""
    reliable = (
        bool(observation["target_visible"])
        and float(observation["target_confidence"]) >= 0.55
        and float(observation["target_identity_confidence"]) >= 0.60
    )
    if reliable:
        if int(observation["track_age"]) < 2:
            memory["state"] = "VERIFY"
            return "SLOW_DOWN", 0.80
        return None

    lost_steps = int(observation["lost_steps"])
    if memory.get("state") in {"LOCKED", "APPROACH", "REACQUIRE"} and lost_steps <= 1:
        memory["state"] = "REACQUIRE"
        return "STOP", 0.92

    direction = memory.get("scan_direction", "SCAN_LEFT")
    memory["scan_direction"] = "SCAN_RIGHT" if direction == "SCAN_LEFT" else "SCAN_LEFT"
    memory["state"] = "SEARCH"
    return direction, 0.75


def propose_moves(observation, memory):
    """Build deduplicated moves from currently observable corridor openings."""
    bearing = float(observation["target_bearing"])
    candidates = []
    if bearing < -12.0 and observation["corridor_left"]:
        candidates.append("VEER_LEFT")
    if bearing > 12.0 and observation["corridor_right"]:
        candidates.append("VEER_RIGHT")
    if observation["corridor_center"]:
        candidates.append("FORWARD")
    if observation["corridor_left"]:
        candidates.append("VEER_LEFT")
    if observation["corridor_right"]:
        candidates.append("VEER_RIGHT")
    return list(dict.fromkeys(candidates))


def progress_contract(observation, memory, candidates):
    """Select a move with short hysteresis, favoring alignment and fewer switches."""
    if not candidates:
        return None

    bearing = float(observation["target_bearing"])
    preferred = (
        "VEER_LEFT" if bearing < -12.0
        else "VEER_RIGHT" if bearing > 12.0
        else "FORWARD"
    )
    last = memory.get("last_action")
    age = int(memory.get("action_age", 0))

    # Keep a recently useful steering commitment unless the target clearly
    # demands the opposite direction or that move is no longer available.
    if last in candidates and age < 2:
        opposite = (
            (last == "VEER_LEFT" and bearing > 18.0)
            or (last == "VEER_RIGHT" and bearing < -18.0)
        )
        if not opposite:
            choice = last
        elif preferred in candidates:
            choice = preferred
        else:
            choice = candidates[0]
    elif preferred in candidates:
        choice = preferred
    else:
        choice = candidates[0]

    if choice == last:
        memory["action_age"] = age + 1
    else:
        memory["action_age"] = 0
    memory["last_action"] = choice
    memory["recent_actions"] = (memory.get("recent_actions", []) + [choice])[-3:]
    return choice


def termination_contract(observation, memory):
    """Return a high-confidence stop when no safe movement proposal is available."""
    memory["state"] = "STOPPED"
    memory["last_action"] = "STOP"
    memory["action_age"] = 0
    return "STOP", 0.98


def decide(observation, memory):
    """Compose safety, tracking, arrival, progress, and termination contracts."""
    memory = dict(memory or {})

    result = safety_contract(observation, memory)
    if result is not None:
        return result[0], result[1], memory

    result = tracking_contract(observation, memory)
    if result is not None:
        return result[0], result[1], memory

    memory["state"] = "LOCKED"
    if observation["target_distance_class"] == "near":
        if (
            abs(float(observation["heading_error"])) <= 15.0
            and float(observation["target_identity_confidence"]) >= 0.80
        ):
            memory["state"] = "ARRIVED"
            memory["last_action"] = "ARRIVED"
            return "ARRIVED", 0.96, memory
        candidates = [
            "VEER_LEFT" if float(observation["target_bearing"]) < 0.0
            else "VEER_RIGHT"
        ]
    else:
        candidates = propose_moves(observation, memory)

    action = progress_contract(observation, memory, candidates)
    if action is None:
        fallback = termination_contract(observation, memory)
        return fallback[0], fallback[1], memory

    memory["state"] = "APPROACH"
    return action, 0.90, memory

# EVOLVE-BLOCK-END
